-- -----------------------------------
-- Table structure for `dvronline`
-- -----------------------------------

DROP TABLE IF EXISTS `dvronline`;
CREATE TABLE `dvronline` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ATMID` varchar(100) CHARACTER SET utf8 NOT NULL,
  `Address` varchar(600) CHARACTER SET utf8 NOT NULL,
  `Location` text CHARACTER SET utf8 NOT NULL,
  `State` varchar(100) CHARACTER SET utf8 NOT NULL,
  `IPAddress` varchar(50) CHARACTER SET utf8 NOT NULL,
  `Rourt ID` varchar(100) CHARACTER SET utf8 NOT NULL,
  `LiveDate` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `UserName` varchar(50) CHARACTER SET utf8 NOT NULL,
  `Password` varchar(50) CHARACTER SET utf8 NOT NULL,
  `Status` varchar(5) CHARACTER SET utf8 NOT NULL,
  `dvrname` varchar(50) CHARACTER SET utf8 NOT NULL,
  `customer` varchar(15) CHARACTER SET utf8 NOT NULL,
  `Bank` varchar(10) CHARACTER SET utf8 NOT NULL,
  `ATMID2` varchar(60) CHARACTER SET utf8 NOT NULL,
  `remark` text CHARACTER SET utf8 NOT NULL,
  `zone` varchar(20) CHARACTER SET utf8 NOT NULL,
  `city` varchar(20) CHARACTER SET utf8 NOT NULL,
  `old_atm` varchar(20) CHARACTER SET utf8 NOT NULL,
  `installationDate` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `project` varchar(20) CHARACTER SET utf8 NOT NULL DEFAULT 'Cloud',
  `sn` int(3) NOT NULL DEFAULT '0',
  `unique_id` varchar(50) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1450 DEFAULT CHARSET=latin1;

